-- Loaded after full migration chain in an empty disposable PostgreSQL fixture.
DO $$ DECLARE merchant uuid:='11111111-1111-4111-8111-111111111111'; v_token text:=repeat('e',64); hash text; claims jsonb; owner_context jsonb; r jsonb; cart uuid; grant_id uuid;
BEGIN
 UPDATE public.merchants SET premium_features='["shared_cart"]',payout_currency=' usd ' WHERE id=merchant;
 INSERT INTO public.mcp_guest_carts(token,items,expires_at,version) VALUES(v_token,'[{"product_id":"44444444-4444-4444-8444-444444444444","quantity":2}]',now()+interval '7 days',7);
 hash:=encode(sha256(v_token::bytea),'hex');
 claims:=jsonb_build_object('role','commerce_cart_shopper','exp',9999999999,'cart_scope','bootstrap','cart_merchant_id',merchant,'cart_principal_id','legacy:mcp:verified','cart_legacy_provider','mcp','cart_legacy_hash',hash);
 PERFORM set_config('request.jwt.claims',claims::text,true);
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'ok' IS DISTINCT FROM 'true' OR (SELECT merchant_id FROM public.mcp_guest_carts c WHERE c.token=v_token) IS DISTINCT FROM merchant THEN RAISE EXCEPTION 'MCP ownership verification/binding failed %',owner_context; END IF;
 IF owner_context->>'currency' IS DISTINCT FROM 'USD' THEN RAISE EXCEPTION 'MCP merchant currency lost'; END IF;
 UPDATE public.merchants SET payout_currency='broken',country='Côte d''Ivoire' WHERE id=merchant;
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'currency' IS DISTINCT FROM 'XOF' THEN RAISE EXCEPTION 'MCP known country currency fallback lost'; END IF;
 UPDATE public.merchants SET payout_currency=' usd ',country='NG' WHERE id=merchant;
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 r:=public.commerce_cart_migrate_legacy('mcp',hash,'bridge-initial',owner_context->'lines','6','USD');
 IF r->>'code' IS DISTINCT FROM 'refresh_required' THEN RAISE EXCEPTION 'Stale legacy row version accepted %',r; END IF;
 r:=public.commerce_cart_migrate_legacy('mcp',hash,'bridge-initial',owner_context->'lines',owner_context->>'legacyVersion','USD');
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Verified MCP migration failed %',r; END IF;
 cart:=(r->'state'->>'cartId')::uuid;
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash); grant_id:=(owner_context->>'grantId')::uuid;
 IF (owner_context->>'cartId')::uuid IS DISTINCT FROM cart OR grant_id IS NULL THEN RAISE EXCEPTION 'Durable grant recovery failed %',owner_context; END IF;
 BEGIN UPDATE public.mcp_guest_carts SET version=8 WHERE token_hash=hash; RAISE EXCEPTION 'Legacy writer was not fenced'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'migrated cart is read-only' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claims',(claims||jsonb_build_object('cart_scope','session','cart_id',cart,'cart_grant_id',grant_id))::text,true);
 r:=public.commerce_cart_mutate(cart,'bridge-write',1,jsonb_build_object('type','set_quantity','lineId',(SELECT id FROM public.commerce_cart_lines WHERE cart_id=cart LIMIT 1),'quantity',3));
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Canonical MCP write failed %',r; END IF;
 PERFORM set_config('request.jwt.claims',claims::text,true);
 DELETE FROM public.mcp_guest_carts WHERE token_hash=hash;
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Continuation lost after legacy retention %',owner_context; END IF;
 UPDATE public.commerce_cart_grants SET revoked_at=now() WHERE id=grant_id;
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'code' IS DISTINCT FROM 'expired' THEN RAISE EXCEPTION 'Revoked grant recovered'; END IF;
 PERFORM set_config('request.jwt.claims',(claims||jsonb_build_object('cart_principal_id','attacker'))::text,true);
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'code' IS DISTINCT FROM 'unauthorized' THEN RAISE EXCEPTION 'Other principal recovered private cart %',owner_context; END IF;
 PERFORM set_config('request.jwt.claims',(claims-'cart_legacy_hash')::text,true);
 owner_context:=public.commerce_cart_legacy_owner_context('mcp',hash);
 IF owner_context->>'code' IS DISTINCT FROM 'unauthorized' THEN RAISE EXCEPTION 'Unattested bootstrap recovered legacy cart'; END IF;
END $$;
DO $$ DECLARE merchant uuid:='11111111-1111-4111-8111-111111111111'; hash text:=encode(sha256('ucp-owned'::bytea),'hex'); c jsonb; ctx jsonb; r jsonb;
BEGIN
 INSERT INTO public.agentic_cart_sessions(cart_id,merchant_id,agent_id,cart_items) VALUES('ucp-owned',merchant,'agent-a','[{"id":"44444444-4444-4444-8444-444444444444","quantity":1}]');
 c:=jsonb_build_object('role','commerce_cart_shopper','exp',9999999999,'cart_scope','bootstrap','cart_merchant_id',merchant,'cart_principal_id','legacy:ucp:verified','cart_legacy_provider','ucp','cart_legacy_hash',hash,'cart_legacy_agent_id','agent-b');
 PERFORM set_config('request.jwt.claims',c::text,true); ctx:=public.commerce_cart_legacy_owner_context('ucp',hash);
 IF ctx->>'ok' IS DISTINCT FROM 'false' OR ctx->>'code' IS DISTINCT FROM 'not_found' THEN RAISE EXCEPTION 'Wrong agent verified UCP ownership'; END IF;
 c:=c||jsonb_build_object('cart_legacy_agent_id','agent-a'); PERFORM set_config('request.jwt.claims',c::text,true);
 UPDATE public.agentic_cart_sessions SET cart_items='[{"id":"44444444-4444-4444-8444-444444444444","quantity":1,"variant_id":"44444444-4444-4444-8444-444444444445","condition":"new","variant_attributes":{"size":"L"}}]' WHERE cart_id='ucp-owned';
 ctx:=public.commerce_cart_legacy_owner_context('ucp',hash);
 IF ctx->>'ok' IS DISTINCT FROM 'true' OR ctx->'lines'->0->'item'->>'variantId' IS DISTINCT FROM '44444444-4444-4444-8444-444444444445' OR ctx->'lines'->0->'item'->>'condition' IS DISTINCT FROM 'new' OR ctx->'lines'->0->'item'->'options'->>'size' IS DISTINCT FROM 'L' THEN RAISE EXCEPTION 'Supported lane identity was not translated %',ctx; END IF;
 UPDATE public.agentic_cart_sessions SET cart_items='[{"id":"44444444-4444-4444-8444-444444444444","quantity":1}]' WHERE cart_id='ucp-owned';
 ctx:=public.commerce_cart_legacy_owner_context('ucp',hash);
 r:=public.commerce_cart_migrate_legacy('ucp',hash,'ucp-import',ctx->'lines',ctx->>'legacyVersion',ctx->>'currency');
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Verified UCP migration failed %',r; END IF;
 ctx:=public.commerce_cart_legacy_owner_context('ucp',hash);
 IF ctx->>'grantId' IS NULL THEN RAISE EXCEPTION 'UCP continuation grant unavailable'; END IF;
 c:=c||jsonb_build_object('cart_legacy_agent_id','agent-b'); PERFORM set_config('request.jwt.claims',c::text,true);
 ctx:=public.commerce_cart_legacy_owner_context('ucp',hash);
 IF ctx->>'code' IS DISTINCT FROM 'unauthorized' THEN RAISE EXCEPTION 'Cross-agent UCP continuation disclosed'; END IF;
END $$;

